fields.styles_css:
/* Expresshipping Careers — modern employer experience */
.eh-careers{--eh-blue:#1476b8;--eh-navy:#102b43;--eh-ink:#183247;--eh-muted:#687b8b;--eh-line:#e4edf3;--eh-pale:#f3f8fc;color:var(--eh-ink);overflow:hidden}
.eh-careers *{box-sizing:border-box}
.eh-careers a{text-decoration:none}
.eh-careers-hero{position:relative;padding:clamp(70px,9vw,126px) 0 90px;background:radial-gradient(circle at 85% 20%,rgba(20,118,184,.11),transparent 28%),linear-gradient(180deg,#f7fbfe 0%,#fff 100%)}
.eh-careers-hero:after{content:"";position:absolute;width:320px;height:320px;border:1px solid rgba(20,118,184,.08);border-radius:50%;right:-170px;bottom:-190px;pointer-events:none}
.eh-eyebrow,.eh-section-kicker{display:inline-flex;align-items:center;gap:10px;color:var(--eh-blue);font-size:11px;font-weight:800;letter-spacing:2px}
.eh-eyebrow-dot{width:8px;height:8px;border-radius:50%;background:var(--eh-blue);box-shadow:0 0 0 5px rgba(20,118,184,.1)}
.eh-careers-hero h1{max-width:720px;margin:23px 0 20px;color:var(--eh-navy);font-size:clamp(43px,6.1vw,76px);font-weight:800;letter-spacing:-3.5px;line-height:1.04}
.eh-careers-hero h1 span,.eh-careers h2 span{color:var(--eh-blue)}
.eh-hero-copy{max-width:590px;color:var(--eh-muted);font-size:17px;line-height:1.85}
.eh-hero-actions{display:flex;align-items:center;flex-wrap:wrap;gap:25px;margin-top:32px}
.eh-btn{display:inline-flex;align-items:center;justify-content:center;gap:13px;padding:15px 22px;border-radius:8px;font-size:14px;font-weight:700;transition:transform .2s,background .2s,box-shadow .2s}
.eh-btn:hover{transform:translateY(-2px)}
.eh-btn-primary{background:var(--eh-blue);color:#fff;box-shadow:0 10px 24px rgba(20,118,184,.18)}
.eh-btn-primary:hover{background:#0e639e;color:#fff}
.eh-text-link{display:inline-flex;gap:10px;align-items:center;color:var(--eh-navy);font-size:14px;font-weight:700}
.eh-text-link:hover{color:var(--eh-blue)}
.eh-location-note{display:flex;align-items:center;gap:10px;margin-top:35px;color:var(--eh-muted);font-size:13px}
.eh-location-note i{color:var(--eh-blue);font-size:17px}
.eh-location-note strong{color:var(--eh-ink)}
.eh-hero-art{position:relative;display:flex;align-items:center;justify-content:center;min-height:390px}
.eh-globe{z-index:2;display:flex;align-items:center;justify-content:center;width:220px;height:220px;border-radius:50%;background:linear-gradient(145deg,#fff,#e6f3fc);box-shadow:inset -15px -18px 35px rgba(20,118,184,.1),0 30px 70px rgba(17,63,94,.12);color:var(--eh-blue)}
.eh-globe i{font-size:112px}
.eh-orbit{position:absolute;border:1px solid rgba(20,118,184,.2);border-radius:50%;transform:rotate(-24deg)}
.eh-orbit-one{width:350px;height:180px}
.eh-orbit-two{width:300px;height:300px;border-style:dashed;opacity:.65}
.eh-float-card{position:absolute;z-index:3;display:flex;align-items:center;gap:12px;padding:13px 16px;border:1px solid rgba(226,237,245,.9);border-radius:12px;background:rgba(255,255,255,.94);box-shadow:0 14px 35px rgba(16,43,67,.1)}
.eh-float-card-top{top:45px;right:-5px}.eh-float-card-bottom{bottom:48px;left:-8px}
.eh-card-icon{display:grid;place-items:center;width:39px;height:39px;border-radius:10px;background:#eaf5fc;color:var(--eh-blue);font-size:18px}
.eh-float-card strong,.eh-float-card small{display:block}.eh-float-card strong{color:var(--eh-navy);font-size:12px}.eh-float-card small{margin-top:3px;color:var(--eh-muted);font-size:10px}
.eh-art-dot{position:absolute;width:9px;height:9px;border-radius:50%;background:#48a9df}.eh-art-dot-one{top:65px;left:55px}.eh-art-dot-two{right:48px;bottom:80px;width:13px;height:13px}.eh-art-dot-three{left:80px;bottom:45px;width:6px;height:6px}
.eh-careers-intro{padding:95px 0 105px}
.eh-careers h2{margin:17px 0 0;color:var(--eh-navy);font-size:clamp(34px,4vw,49px);font-weight:800;letter-spacing:-1.8px;line-height:1.12}
.eh-intro-copy,.eh-roles-heading>div:last-child p{margin:0;color:var(--eh-muted);font-size:15px;line-height:1.9}
.eh-value-grid{margin-top:48px}
.eh-value-card{position:relative;height:100%;min-height:230px;padding:27px 24px;border:1px solid var(--eh-line);border-radius:12px;background:#fff;transition:transform .25s,border-color .25s,box-shadow .25s}
.eh-value-card:hover{transform:translateY(-5px);border-color:#c7dfef;box-shadow:0 18px 35px rgba(20,65,96,.07)}
.eh-value-icon{display:grid;place-items:center;width:46px;height:46px;border-radius:11px;background:#edf6fc;color:var(--eh-blue);font-size:21px}
.eh-value-card h3{margin:22px 0 9px;color:var(--eh-navy);font-size:17px;font-weight:750}
.eh-value-card p{margin:0;color:var(--eh-muted);font-size:13px;line-height:1.8}
.eh-card-index{position:absolute;top:26px;right:24px;color:#a9bac7;font-size:11px;font-weight:800;letter-spacing:1px}
.eh-careers-life{padding:20px 0 100px}
.eh-life-panel{padding:clamp(30px,5vw,66px);border-radius:18px;background:var(--eh-navy);color:#fff;overflow:hidden}
.eh-kicker-light{color:#8fcdf3}
.eh-life-panel h2,.eh-careers-cta h2{margin:18px 0;color:#fff;font-size:clamp(35px,4.3vw,52px);font-weight:800;letter-spacing:-1.8px;line-height:1.12}
.eh-life-panel h2 span,.eh-careers-cta h2 span{color:#78c4f0}
.eh-life-panel> .row>div:first-child>p,.eh-careers-cta p{max-width:490px;color:#c1d1dc;font-size:14px;line-height:1.9}
.eh-life-link{display:inline-flex;gap:10px;margin-top:14px;color:#fff;font-size:14px;font-weight:700}
.eh-work-list{border-top:1px solid rgba(255,255,255,.17)}
.eh-work-item{display:grid;grid-template-columns:38px 1fr 20px;gap:15px;align-items:start;padding:23px 0;border-bottom:1px solid rgba(255,255,255,.17)}
.eh-work-item>span{color:#78c4f0;font-size:12px;font-weight:800}
.eh-work-item h3{margin:0 0 6px;color:#fff;font-size:16px;font-weight:700}
.eh-work-item p{margin:0;color:#b7c9d6;font-size:12px;line-height:1.7}
.eh-work-item>i{color:#8fcdf3}
.eh-careers-roles{padding:25px 0 105px}
.eh-roles-heading{margin-bottom:42px}
.eh-no-openings{display:flex;gap:25px;align-items:flex-start;padding:35px;border:1px solid var(--eh-line);border-radius:14px;background:linear-gradient(120deg,#f7fbfe,#fff)}
.eh-no-openings-icon{flex:0 0 54px;display:grid;place-items:center;width:54px;height:54px;border-radius:13px;background:#e7f3fb;color:var(--eh-blue);font-size:23px}
.eh-open-label{color:var(--eh-blue);font-size:10px;font-weight:800;letter-spacing:1.8px}
.eh-no-openings h3{margin:9px 0;color:var(--eh-navy);font-size:21px;font-weight:750}
.eh-no-openings p{max-width:680px;margin:0 0 20px;color:var(--eh-muted);font-size:14px;line-height:1.8}
.eh-btn-outline{border:1px solid #c8dce9;color:var(--eh-navy);background:#fff}
.eh-btn-outline:hover{border-color:var(--eh-blue);color:var(--eh-blue)}
.eh-roles-footnote{display:flex;gap:9px;margin:18px 0 0;color:var(--eh-muted);font-size:12px;line-height:1.7}
.eh-roles-footnote i{color:var(--eh-blue)}
.eh-careers-cta{padding:0 0 100px}
.eh-cta-inner{display:flex;align-items:center;justify-content:space-between;gap:30px;padding:clamp(30px,5vw,58px);border-radius:17px;background:linear-gradient(115deg,#116da9,#174d78)}
.eh-careers-cta h2{font-size:clamp(31px,4vw,45px)}
.eh-careers-cta p{margin-bottom:0}
.eh-btn-white{flex:0 0 auto;background:#fff;color:var(--eh-navy)}
.eh-btn-white:hover{background:#eaf5fc;color:var(--eh-blue)}
@media(max-width:991px){.eh-careers-hero{padding-top:70px}.eh-hero-art{min-height:340px}.eh-careers-intro{padding:70px 0}.eh-careers-life{padding-bottom:75px}.eh-careers-roles{padding-bottom:75px}}
@media(max-width:575px){.eh-careers-hero h1{letter-spacing:-2px}.eh-hero-art{min-height:290px;margin-top:8px}.eh-globe{width:165px;height:165px}.eh-globe i{font-size:82px}.eh-orbit-one{width:270px;height:145px}.eh-orbit-two{width:235px;height:235px}.eh-float-card{padding:10px 11px}.eh-float-card-top{right:0;top:25px}.eh-float-card-bottom{left:0;bottom:20px}.eh-hero-actions{align-items:flex-start;flex-direction:column;gap:17px}.eh-value-card{min-height:0}.eh-no-openings{padding:23px;gap:15px;flex-direction:column}.eh-cta-inner{align-items:flex-start;flex-direction:column}.eh-careers-cta{padding-bottom:65px}}
@media(prefers-reduced-motion:reduce){.eh-careers *{scroll-behavior:auto!important;transition:none!important}}
